import { useState } from "react";
import axios from "axios";

function CrearProducto() {

  const [form, setForm] = useState({
    tipo_producto: "esmeralda",
    color: "",
    peso: "",
    tratamiento: "",
    valor: "",
    stock: "",
    imagen: null,
    certificado: null,

    // joya
    tiene_esmeralda: false,
    oro: false,
    oro_rosado: false,
    plata: false
  });

  // =========================
  // MANEJO DE INPUTS
  // =========================
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;

    if (type === "checkbox") {
      setForm({ ...form, [name]: checked });
    } else if (type === "file") {
      setForm({ ...form, [name]: e.target.files[0] });
    } else {
      setForm({ ...form, [name]: value });
    }
  };

  // =========================
  // ENVIAR FORMULARIO
  // =========================
  const handleSubmit = async (e) => {
    e.preventDefault();

    const data = new FormData();

    Object.keys(form).forEach((key) => {
      if (typeof form[key] === "boolean") {
        data.append(key, form[key] ? 1 : 0);
      } else {
        data.append(key, form[key]);
      }
    });

    try {
      await axios.post("http://localhost:3000/productos", data, {
        headers: {
          "Content-Type": "multipart/form-data",
          Authorization: localStorage.getItem("token"), // 🔐
        },
      });

      alert("Producto creado 🔥");

    } catch (error) {
      console.error(error);
      alert("Error al crear producto");
    }
  };

  return (
    <div>
      <h2>Publicar nueva esmeralda</h2>

      <form onSubmit={handleSubmit}>

        {/* TIPO */}
        <select name="tipo_producto" onChange={handleChange}>
          <option value="esmeralda">Esmeralda</option>
          <option value="joya">Joya</option>
        </select>

        {/* DATOS GENERALES */}
        <input name="color" placeholder="Color" onChange={handleChange} />
        <input name="peso" placeholder="Peso" onChange={handleChange} />
        <input name="tratamiento" placeholder="Tratamiento" onChange={handleChange} />
        <input name="valor" placeholder="Valor" type="number" onChange={handleChange} />
        <input name="stock" placeholder="Stock" type="number" onChange={handleChange} />

        {/* ARCHIVOS */}
        <label>Imagen:</label>
        <input type="file" name="imagen" onChange={handleChange} />

        <label>Certificado:</label>
        <input type="file" name="certificado" onChange={handleChange} />

        {/* 💍 CAMPOS JOYA */}
        {form.tipo_producto === "joya" && (
          <>
            <h3>Datos de la joya</h3>

            <label>
              <input type="checkbox" name="tiene_esmeralda" onChange={handleChange} />
              Tiene esmeralda
            </label>

            <label>
              <input type="checkbox" name="oro" onChange={handleChange} />
              Oro
            </label>

            <label>
              <input type="checkbox" name="oro_rosado" onChange={handleChange} />
              Oro rosado
            </label>

            <label>
              <input type="checkbox" name="plata" onChange={handleChange} />
              Plata
            </label>
          </>
        )}

        <button type="submit">Publicar</button>
      </form>
    </div>
  );
}

export default CrearProducto;
